function removeDuplicates(arr) {
    return [...new Set(arr)];
}

// Example usage:
let arr = [1, 2, 3, 2, 4, 5, 5, 6];
console.log(removeDuplicates(arr));  // Output: [1, 2, 3, 4, 5, 6]

// Alternatively, you can use a more traditional approach with a for loop:
function removeDuplicates(arr) {
    let result = [];
    for (let i = 0; i < arr.length; i++) {
        if (arr.indexOf(arr[i]) === -1) {
            result.push(arr[i]);
        }
    }
    return result;
}

// Example usage:
let arr = [1, 2, 3, 2, 4, 5, 5, 6];
console.log(removeDuplicates(arr));  // Output: [1, 2, 3, 4, 5, 6]
